import {keplerIcon as robot} from './character.js';
import {uiQuery,uiQueryAll} from './router.js';
import {mountReader,destroyReader} from './pdf-reader.js';
import {coursePriority} from './progress-core.js';
import {courseResources,attendanceSignal,parseCourseRoute,courseMatches,pdfCandidate,safeResourceUrl} from './course-core.js';
import {taskReminder} from './panel-core.js';
const $=s=>uiQuery(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs={overview:'Genel bakış',files:'Dosyalar',announcements:'Duyurular',assignments:'Ödevler',syllabus:'İzlence'};

const folderIcon=`<svg viewBox="0 0 48 40" aria-hidden="true"><path d="M3 10V5h15l5 5h21v25H3Z" fill="currentColor" opacity=".35"/><path d="M3 13h41v22H3Z" fill="currentColor" opacity=".65"/><path d="M3 13h41v22H3Z" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>`;
const stamp=value=>{if(!value||!Number.isFinite(+new Date(value)))return 'Kontrol zamanı aktarılmadı';return new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'long',year:'numeric',...(value.includes('T')?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(value.length===10?value+'T12:00:00+03:00':value));};
const href=(id,tab='overview')=>'#/courses/'+encodeURIComponent(id)+'/'+tab;
const sourceLink=(url,title,cls='')=>{const safe=safeResourceUrl(url,location.origin);return safe?`<a class="workspace-link ${cls}" href="${esc(safe)}" target="_blank" rel="noopener noreferrer">${esc(title)} <span aria-hidden="true">↗</span></a>`:'<span class="workspace-muted">Kaynak bağlantısı yok / desteklenmiyor</span>';};
let data,getCompleted=()=>({}),attendance=window.keplerAttendanceOverview||{items:[],state:'loading',updatedAt:null},route=null,blobUrl=null,previewAbort=null,requestId=0;
const signal=course=>attendanceSignal(attendance.items.find(i=>i.courseId===course.id),attendance.state);
const stale=at=>!at||(Date.now()-new Date(at))/36e5>data.staleAfterHours;
const evidence=(at,label='Kaynak kontrolü')=>`<small class="workspace-evidence">${label}: ${esc(stamp(at))}${stale(at)?' · Eski / eksik kontrol; yeniden doğrula.':''}</small>`;
const inventoryEvidence=course=>{const inventory=data.classFiles?.courses?.[course.id];return inventory?`<div class="inventory-dates"><span>Sınıf Dosyaları: ${esc(stamp(data.classFiles.checkedAt))} · ${inventory.entries.length} kayıt</span><span>Ders Dosyaları: ${esc(stamp(inventory.courseFilesCheckedAt))} · ${inventory.courseEntries?.length??'?'} kayıt</span></div>`:'<small class="workspace-evidence">Dosya envanteri yükleniyor / erişilemedi.</small>'};
const signalHTML=course=>{const s=signal(course);return `<span class="course-signal signal-${s.tone}"><span class="signal-icon" aria-hidden="true">${s.icon}</span>${esc(s.label)}</span>`;};
function clearPreview(){destroyReader();requestId++;previewAbort?.abort();previewAbort=null;if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl=null;}
function renderFolders(){
 if(!data)return;const query=$('#folderSearch').value,filter=$('#folderFilter').value,courses=data.courses.filter(c=>courseMatches(data,c,query,filter,signal(c)));
 $('#courseCount').textContent=data.courses.length+' güncel ders';$('#folderResult').textContent=`${courses.length} / ${data.courses.length} klasör · Dosya sayıları aktarılan bağlantılardır; tam Ninova envanteri değildir.`;
 $('#courseGrid').setAttribute('aria-busy','false');$('#courseGrid').innerHTML=courses.length?courses.map((c,index)=>{const priority=coursePriority(data,c.id,{completed:getCompleted()}),files=courseResources(data,c),announcements=data.announcements.filter(a=>a.courseId===c.id),tasks=data.tasks.filter(t=>t.courseId===c.id&&t.kind==='assignment');return `<article class="course-folder priority-${priority.tone}" style="--folder-accent:${['#cfb8f5','#e7b99a','#a6c4b4'][index%3]}"><a class="folder-open" href="${href(c.id)}"><div class="folder-top">${folderIcon}<span>${esc(c.id)}</span><span aria-hidden="true">↗</span></div><h3>${esc(c.nameTr||c.name||'Ders adı aktarılmadı')}</h3><p class="folder-subtitle">${esc(data.classFiles?.courses?.[c.id]?.identityBasis?'Kişisel takvimdeki ders adı':c.name===c.id?'Tam ders adı aktarılmadı':c.name)}</p><div class="folder-counts"><span>${files.length} kaynak</span><span>${announcements.length} duyuru</span><span>${tasks.length} ödev</span></div>${priority.rank>=3?`<p class="folder-priority">${esc(priority.label)}</p>`:''}<div data-course-signal="${esc(c.id)}">${signalHTML(c)}</div><span class="folder-enter">Klasörü aç <span aria-hidden="true">→</span></span></a><details class="folder-evidence"><summary>Kontrol kapsamı</summary>${evidence(c.verifiedAt,'Ders bilgisi kaydı')}${inventoryEvidence(c)}</details></article>`}).join(''):`<div class="workspace-state"><h3>Eşleşen ders klasörü yok.</h3><p>${filter==='critical'&&attendance.state!=='ready'?'Yoklama okunmadan kritik ders filtresi hesaplanamaz.':'Aramayı veya filtreyi değiştir. Dosya aktarılmamış olması, Ninova’da dosya olmadığı anlamına gelmez.'}</p><button type="button" class="workspace-button" data-reset-folders>Filtreyi temizle</button></div>`;
}
function resourceRows(course,files,emptyLabel){
 if(!files.length)return `<div class="workspace-state"><h3>${esc(emptyLabel)}</h3><p>Tam dosya envanteri aktarılmadı. Mevcut kayıttan yokluk sonucu çıkarılamaz.</p>${sourceLink(course.sourceUrl,'Dersin Ninova sayfasına git')}</div>`;
 return `<div class="resource-list">${files.map(f=>{const index=courseResources(data,course).findIndex(r=>r.url===f.url);return `<article class="resource-row"><span class="resource-icon" aria-hidden="true">${f.syllabus?'≡':'▤'}</span><div><h4>${esc(f.title)}</h4><p>${esc(f.contexts.join(' · '))}</p><span class="resource-kind">${f.otherInstructor?'Başka öğretmene ait ortak izlence · güncel sınıf izlencesi olarak seçilmedi':f.preview?'Özel PDF kopyası · imza / SHA-256 doğrulandı':pdfCandidate(f,location.origin)?'Doğrudan PDF bağlantısı · erişim henüz doğrulanmadı':new URL(f.url,location.origin).hostname==='drive.google.com'?'Drive kaynağı · erişim izne bağlı':'Ninova kaynak sayfası · oturum gerekebilir'}</span>${evidence(f.verifiedAt)}</div><div class="resource-actions">${sourceLink(f.url,'Kaynağı aç')}${pdfCandidate(f,location.origin)?`<button type="button" class="workspace-button" data-preview-resource="${index}">${f.preview?'PDF’yi büyük aç':'PDF erişimini denetle'}</button>`:f.syllabus?'<span class="preview-unavailable">Doğrudan PDF aktarılmadı</span>':''}${f.kind==='folder'?`<button type="button" class="workspace-button" data-folder-open="${esc((f.folder==='/'?'':f.folder)+'/'+f.title)}">Alt klasörü aç →</button>`:''}</div></article>`;}).join('')}</div>`;
}
function attendancePanel(course){const item=attendance.items.find(i=>i.courseId===course.id),s=signal(course);return `<div class="course-attendance-card"><div data-course-signal="${esc(course.id)}">${signalHTML(course)}</div><p data-course-attendance-text>${esc(s.text)}</p><small data-course-attendance-time>${attendance.updatedAt?'Yerel kayıt: '+esc(stamp(attendance.updatedAt))+' İstanbul':'Bulut kayıt zamanı bilinmiyor.'}</small><a class="workspace-link" href="#attendance" data-open-panel="attendance" data-attendance-course="${esc(course.id)}">Kişisel yoklama kayıtlarını aç →</a><p class="workspace-muted">Yarım = 0,5 oturum. Limit kişisel ayarındır; Ninova katılımından türetilmez.</p></div>`;}
function announcementsHTML(course){const list=data.announcements.filter(a=>a.courseId===course.id).slice().sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||''));return list.length?`<div class="course-feed">${list.map(a=>`<article class="course-notice"><div class="notice-meta">${a.status==='past_event'?'Geçmiş duyuru':a.status==='actionable_blocker'?'Kaynak sorunu':'Duyuru'}${a.publishedAt?' · '+esc(stamp(a.publishedAt)):''}</div><h4>${esc(a.title)}</h4><details class="notice-expand"><summary>Duyuru metnini oku</summary><p>${esc(a.body)}</p></details><div class="resource-actions">${sourceLink(a.sourceUrl,'Ninova duyurusu')}${a.resourceUrl?sourceLink(a.resourceUrl,'Ek kaynak'):''}</div>${evidence(a.verifiedAt)}</article>`).join('')}</div>`:`<div class="workspace-state"><h3>Duyuru kaydı aktarılmadı.</h3><p>Bu durum yeni duyuru olmadığı anlamına gelmez. Ninova’dan yeniden kontrol et.</p>${sourceLink(course.sourceUrl,'Ders kaynağını aç')}</div>`;}
function tasksHTML(course){const tasks=data.tasks.filter(t=>t.courseId===course.id).slice().sort((a,b)=>(a.dueAt||a.date).localeCompare(b.dueAt||b.date));return tasks.length?`<p class="workspace-muted">Kişisel işaretlerin bu tarayıcıda kalır. Geçmiş tarih, kaçırılmış teslim kanıtı değildir.</p><div class="course-tasks">${tasks.map(t=>{const reminder=taskReminder(t),s=t.submission;return `<article class="course-task"><div class="notice-meta">${t.kind==='assignment'?'Ninova ödevi':t.kind==='personal'?'Kişisel hedef · Ninova tesliminden ayrı':'Dönüm noktası'} · ${esc(reminder.label)}</div><h4>${esc(t.title)}</h4><p class="course-task-date">${esc(stamp(t.dueAt||t.date))}${t.dueAt?' · İstanbul':' · Saat bilinmiyor'}</p><p>${esc(t.summary)}</p>${s?`<p class="submission-snapshot">Son gözlenen kendi hesabın: <strong>${s.ownUploaded}/${s.expectedFiles} dosya</strong> · Güncel kabul / not / zamanında teslim sonucu bilinmiyor.</p>${s.scope==='group'?'<p class="group-caveat">Bir grup üyesinin yüklemesi yeterli. Kendi sıfır kaydın grup başarısızlığı değildir; grup sonucu bilinmiyor.</p>':''}`:''}${(t.requirements||[]).length?`<details><summary>Teslim içeriği</summary><ul>${t.requirements.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></details>`:''}<div class="resource-actions">${t.sourceUrl?sourceLink(t.sourceUrl,'Ödev / hedef kaynağı'):'<span class="workspace-muted">Ninova kaynağı doğrulanmadı</span>'}</div><label class="course-plan-check"><input type="checkbox" data-task="${esc(t.id)}" ${getCompleted()[t.id]?'checked':''}><span>Kendi planımda tamamladım <small>Yalnızca bu tarayıcıda · Ninova durumunu değiştirmez</small></span></label>${t.verification==='verified'?evidence(t.verifiedAt):'<small class="workspace-evidence">Kişisel / doğrulanmamış kayıt</small>'}</article>`;}).join('')}</div>`:`<div class="workspace-state"><h3>Bu derse bağlı iş aktarılmadı.</h3><p>Ödev olmadığı anlamına gelmez. Dersi belirsiz kişisel işler genel Ödevlerim bölümünde kalır.</p>${sourceLink(course.sourceUrl,'Ninova’dan kontrol et')}</div>`;}
function renderDetail(){
 if(!route||route.missing)return;const c=route.course,files=courseResources(data,c),tab=route.tab;
 const counts={files:files.length,announcements:data.announcements.filter(a=>a.courseId===c.id).length,assignments:data.tasks.filter(t=>t.courseId===c.id).length,syllabus:files.filter(f=>f.syllabus).length};
 let content='';
 if(tab==='overview')content=`<div class="course-overview-grid"><section class="course-info-block"><h3>Dersin çalışma alanı</h3><p>${esc(c.name||'Tam adı aktarılmadı')}</p><div class="course-schedule">${(c.schedule||[]).map(s=>`<p><strong>${['','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'][s[0]]} · ${esc(s[1])}</strong><span>${esc(s[2])}</span></p>`).join('')||'<p>Ders programı aktarılmadı.</p>'}</div>${evidence(c.scheduleCheckedAt,'Program kaydı')}<p class="workspace-muted">Bu program eski kaynak kaydıdır. Güncel duyurular ve tarihli takvim istisnaları önceliklidir.</p>${sourceLink(c.sourceUrl,'Ninova ders sayfası')}</section><section class="course-info-block"><h3>Kişisel yoklama sinyali</h3>${attendancePanel(c)}</section></div><div class="course-shortcuts"><a href="${href(c.id,'files')}"><strong>${counts.files}</strong> kaynak bağlantısı <span>Dosyaları aç →</span></a><a href="${href(c.id,'announcements')}"><strong>${counts.announcements}</strong> aktarılmış duyuru <span>Duyuruları gör →</span></a><a href="${href(c.id,'assignments')}"><strong>${counts.assignments}</strong> iş / hedef <span>Ödevlere geç →</span></a></div>${c.rules?`<section class="course-info-block"><h3>Kaynakta aktarılan ders kuralları</h3><p>${esc(c.rules)}</p>${evidence(c.verifiedAt)}</section>`:''}<p class="workspace-muted">Kapsam: ${c.coverage==='unknown'?'eksik / bilinmiyor':'kısmi'}. Yalnızca aktarılmış kaynaklar gösterilir.</p>`;
 if(tab==='files')content=`<div class="tab-heading"><div><h3>Dosyalar & kaynaklar</h3><p>Sınıf dosyaları, ödev ekleri ve duyuru bağlantıları bir arada. Aynı URL tek kez gösterilir.</p></div></div><details class="inventory-scope"><summary>${data.classFiles?'73 Ninova kaydı · kapsam ve kontrol tarihleri':'Envanter yükleniyor / erişilemedi'}</summary>${inventoryEvidence(c)}<p>56 Sınıf Dosyaları + 17 Ders Dosyaları kaydı. Harici bağlantı hedefleri taranmadı. Yeni keşfedilen kayıtlar yeni yükleme iddiası taşımaz.</p></details><label class="workspace-select resource-folder-select">Alt klasör<select id="resourceFolder"><option value="all">Tüm alt klasörler</option>${[...new Set(files.map(f=>f.folder).filter(Boolean))].map(folder=>`<option value="${esc(folder)}">${esc(folder==='/'?'Bölüm kökleri':folder)}</option>`).join('')}</select></label><label class="workspace-search file-search" for="resourceSearch"><span aria-hidden="true">⌕</span><input id="resourceSearch" type="search" placeholder="Bu klasörde dosya ara…"></label><p id="fileResult" class="workspace-result" role="status"></p><div id="resourceRows">${resourceRows(c,files,'Dosya bağlantısı aktarılmadı.')}</div><div id="pdfPreview" hidden></div>`;
 if(tab==='announcements')content=`<div class="tab-heading"><h3>Ders duyuruları</h3><p>Aktarılan kayıtlar; tam arşiv veya canlı akış değildir.</p></div>${announcementsHTML(c)}`;
 if(tab==='assignments')content=`<div class="tab-heading"><h3>Ödevler & kişisel hazırlıklar</h3></div>${tasksHTML(c)}`;
 if(tab==='syllabus')content=`<div class="tab-heading"><h3>İzlence / syllabus</h3><p>PDF okuyucu yalnızca erişilebilir gerçek PDF içeriği için açılır. Oturum isteyen sayfalar PDF olarak gömülmez.</p></div>${resourceRows(c,files.filter(f=>f.syllabus),'İzlence kaynağı aktarılmadı.')}<div id="pdfPreview" hidden></div>`;
 $('#courseDetail').innerHTML=`<div class="course-breadcrumb"><a href="#/courses">← Tüm ders klasörleri</a><label>Ders değiştir<select id="courseSwitcher" aria-label="Ders değiştir">${data.courses.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.id)}</option>`).join('')}</select></label></div><header class="course-detail-header"><div class="course-cover-icon">${folderIcon}</div><div><p class="workspace-kicker">${esc(c.id)} / DERS KLASÖRÜ</p><h2 id="courseDetailTitle" tabindex="-1">${esc(c.nameTr||c.name)}</h2><p>${esc(c.name===c.id?'Tam ders adı henüz aktarılmadı':c.name)}</p></div><div class="course-header-signal" data-course-signal="${esc(c.id)}">${signalHTML(c)}</div></header><div class="course-verification"><details><summary>Kaynaklar ve kontrol kapsamı</summary>${evidence(c.verifiedAt,'Ders bilgisi kaydı')}${inventoryEvidence(c)}<p>${esc(data.classFiles?.courses[c.id]?.identityBasis||'Ders bilgisi ve dosya envanteri farklı tarihlerde kontrol edilmiş olabilir.')}</p></details></div><nav class="course-tabs" aria-label="${esc(c.id)} bölümleri">${Object.entries(tabs).map(([key,label])=>`<a href="${href(c.id,key)}" ${tab===key?'aria-current="page"':''}>${label}${counts[key]!==undefined?`<span>${counts[key]}</span>`:''}</a>`).join('')}</nav><div id="courseTabContent" class="course-tab-content">${content}</div><div class="course-kepler-note">${robot}<p><strong>Kepler’in notu</strong><span>${tab==='syllabus'?'Özel PDF kopyasını okuyabilir veya özgün Ninova kaynağını açabilirsin. Ortak bölümdeki farklı öğretmen izlenceleri güncel sınıf izlencesi olarak seçilmez.':tab==='assignments'?'Hazır işaretin senin çalışma planın. Ninova’ya yükleme, kabul veya grup teslimi yerine geçmez.':tab==='announcements'?'Son kontrol tarihine bak. Eski bir duyuru yeni bir duyuruyla değişmiş olabilir.':tab==='files'?'Buradaki bağlantılar kaynak sayfaları olabilir. Görmediğim dosya adlarını veya erişim durumunu tahmin etmem.':'Kişisel yoklama kayıtların ile Ninova bilgilerini ayrı tutuyorum. Belirsiz günleri devamsız saymıyorum.'}</span></p></div>`;
 $('#courseSwitcher').addEventListener('change',e=>{location.hash=href(e.target.value,tab)});
 const filterFiles=()=>{const query=$('#resourceSearch').value.toLocaleLowerCase('tr-TR'),folder=$('#resourceFolder').value,filtered=files.filter(f=>(folder==='all'||f.folder===folder)&&[f.title,...f.contexts].join(' ').toLocaleLowerCase('tr-TR').includes(query));$('#fileResult').textContent=filtered.length+' / '+files.length+' kaynak';$('#resourceRows').innerHTML=filtered.length?resourceRows(c,filtered,''): '<div class="workspace-state">Bu aramayla eşleşen kaynak yok. Aramayı temizleyebilirsin.</div>';};$('#resourceSearch')?.addEventListener('input',filterFiles);$('#resourceFolder')?.addEventListener('change',filterFiles);
 if(tab==='syllabus'){const index=files.findIndex(f=>f.preview);if(index>=0)previewPDF(index);}
}
function routeChanged(focus=true){
 if(!data)return;clearPreview();route=parseCourseRoute(location.hash,data.courses);const detail=!!route;
 document.body.classList.toggle('course-mode',detail);$('#courseHome').hidden=detail;$('#courseDetail').hidden=!detail;
 if(route?.missing)$('#courseDetail').innerHTML='<div class="workspace-state"><h2 id="courseDetailTitle" tabindex="-1">Bu ders klasörü bulunamadı.</h2><p>Adres geçersiz veya ders bu veri kopyasında yok.</p><a class="workspace-link" href="#/courses">Tüm ders klasörlerine dön →</a></div>';
 else if(route)renderDetail();
 else renderFolders();
 if(route&&!route.missing)$('.command-location').textContent='Kepler / '+route.course.id+' / '+tabs[route.tab];
 if(focus&&route&&!route.missing){$('#courseDetailTitle')?.focus({preventScroll:true});}
 updateCompanion();
}
async function previewPDF(index){
 const course=route?.course;if(!course)return;const file=courseResources(data,course)[index],candidate=pdfCandidate(file,location.origin);if(!candidate)return;
 clearPreview();const token=requestId;previewAbort=new AbortController();const area=$('#pdfPreview');if(!area)return;
 area.hidden=false;area.innerHTML=`<section class="pdf-reader"><div class="pdf-toolbar"><h3>${esc(file.title)}</h3><button type="button" class="workspace-button" data-close-preview>Okuyucuyu kapat</button></div><p role="status">PDF erişimi denetleniyor…</p><p class="workspace-muted">İçerik PDF olarak doğrulanmadan önizleme açılmaz.</p></section>`;area.scrollIntoView({block:'nearest'});
 const timer=setTimeout(()=>previewAbort?.abort(),12000);let reader;
 try{
  const response=await fetch(candidate,{signal:previewAbort.signal,credentials:new URL(candidate).origin===location.origin?'same-origin':'omit',redirect:'error',cache:'no-store'});
  if(!response.ok)throw Error(response.status===401||response.status===403?'Kaynak giriş veya erişim izni istiyor.':'PDF kaynağı HTTP '+response.status+' yanıtı verdi.');
  if(!/^application\/pdf(?:;|$)/i.test(response.headers.get('Content-Type')||''))throw Error('Kaynak PDF yerine bir web / giriş sayfası döndürdü.');
  const max=20*1024*1024;if(Number(response.headers.get('Content-Length'))>max)throw Error('Belge 20 MB önizleme sınırını aşıyor.');
  reader=response.body.getReader();let bytes=0;const chunks=[];
  while(true){const {done,value}=await reader.read();if(done)break;bytes+=value.byteLength;if(bytes>max){await reader.cancel();throw Error('Belge 20 MB önizleme sınırını aşıyor.');}chunks.push(value);}
  const blob=new Blob(chunks,{type:'application/pdf'});if(!new TextDecoder().decode(await blob.slice(0,5).arrayBuffer()).startsWith('%PDF-'))throw Error('İçerik gerçek PDF başlığı taşımıyor.');
  if(token!==requestId)return;blobUrl=URL.createObjectURL(blob);
  area.innerHTML=`<section class="pdf-reader"><div class="pdf-toolbar"><h3>${esc(file.title)}</h3><button type="button" class="workspace-button" data-close-preview>Okuyucuyu kapat</button></div><p class="pdf-status" role="status">PDF içeriğine bu oturumda erişildi. Belge tarihi / güncelliği ayrıca kaynağından doğrulanmalı.</p><div class="pdf-actions"><button type="button" class="workspace-button" data-reader-focus>Okuma alanını büyüt</button><a class="workspace-link" href="${blobUrl}" target="_blank" rel="noopener">PDF’yi ayrı sekmede büyüt ↗</a>${sourceLink(file.url,'Özgün kaynak')}</div><div class="pdf-object" data-pdf-mount><p role="status">PDF okuyucu hazırlanıyor…</p></div><p class="workspace-muted">Okuyucu bu özel panelde çalışır. Sayfayı, yakınlaştırmayı veya metin görünümünü kullanabilir; PDF’yi ayrı sekmede açabilirsin.</p></section>`;
 await mountReader(area.querySelector('[data-pdf-mount]'),blob);
 }catch(error){if(token!==requestId)return;area.innerHTML=`<section class="pdf-reader"><div class="pdf-toolbar"><h3>PDF burada önizlenemedi</h3><button type="button" class="workspace-button" data-close-preview>Kapat</button></div><p role="status">${esc(error.name==='AbortError'?'Erişim denetimi zaman aşımına uğradı.':error instanceof TypeError?'Oturum, CORS veya ağ nedeniyle belge okunamadı.':error.message)}</p><p>Belgeye erişilemedi; içerik okunmuş sayılmaz. Ninova oturumunu kaynak sekmesinde açabilirsin. Bu panel giriş bilgisi istemez veya saklamaz.</p>${sourceLink(file.url,'Kaynakta aç')} <button type="button" class="workspace-button" data-preview-resource="${index}">Yeniden denetle</button></section>`;}
 finally{clearTimeout(timer);reader?.releaseLock();}
}
function updateCompanion(){const text=route&&!route.missing?`${route.course.id} klasöründesin. ${tabs[route.tab]} bölümünü görüntülüyorsun.`:'Ders klasörlerinden kaynaklarına geçebilir veya kayıt özetini asistana sorabilirsin.';$('#companionContext')?.replaceChildren(document.createTextNode(text));}
function initCompanion(){
 $('#keplerCompanion').innerHTML=`<button type="button" class="companion-toggle" id="companionToggle" aria-label="Kepler kısayollarını aç" aria-expanded="false" aria-controls="companionPanel">${robot}<span>Kepler<span class="companion-toggle-hint">Kısayollar</span></span></button><div id="companionPanel" class="companion-panel" hidden><div><h2>Birlikte netleştirelim.</h2><button type="button" id="companionClose" aria-label="Kepler kısayollarını kapat">×</button></div><p id="companionContext"></p><a href="#/courses">Ders klasörlerimi aç →</a><a href="#assistant">Kayıt özeti sor →</a><a href="#week">Kişisel yoklamamı gör →</a><small>Kayıtlı veriye dayalı kısayollar · canlı bağlantı / serbest sohbet yok</small></div>`;
 const toggle=open=>{$('#companionPanel').hidden=!open;$('#companionToggle').setAttribute('aria-expanded',String(open));if(!open)$('#companionToggle').focus({preventScroll:true});};
 $('#companionToggle').addEventListener('click',()=>toggle($('#companionPanel').hidden));$('#companionClose').addEventListener('click',()=>toggle(false));
 $('#keplerCompanion').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();toggle(false)}});
 $('#companionPanel').addEventListener('click',e=>{if(e.target.closest('a'))toggle(false)});
 document.addEventListener('click',e=>{if(!e.target.closest('#keplerCompanion')){$('#companionPanel').hidden=true;$('#companionToggle').setAttribute('aria-expanded','false')}});
}
export function initCourseWorkspace(value,completed){
 data=value;getCompleted=completed;attendance=window.keplerAttendanceOverview||attendance;
 initCompanion();$('#folderSearch').addEventListener('input',renderFolders);$('#folderFilter').addEventListener('change',renderFolders);
 $('#courses').addEventListener('click',e=>{const reset=e.target.closest('[data-reset-folders]');if(reset){$('#folderSearch').value='';$('#folderFilter').value='all';renderFolders();$('#folderSearch').focus();}const folder=e.target.closest('[data-folder-open]');if(folder&&$('#resourceFolder')){$('#resourceFolder').value=folder.dataset.folderOpen;$('#resourceFolder').dispatchEvent(new Event('change'));$('#resourceFolder').focus();}if(e.target.closest('[data-reader-focus]')){const reader=$('.pdf-reader');if(reader.requestFullscreen)reader.requestFullscreen().catch(()=>reader.scrollIntoView({block:'start'}));else reader.scrollIntoView({block:'start'});}const preview=e.target.closest('[data-preview-resource]');if(preview)previewPDF(Number(preview.dataset.previewResource));if(e.target.closest('[data-close-preview]')){clearPreview();$('#pdfPreview').hidden=true;$('#pdfPreview').replaceChildren();const focus=$('[data-preview-resource]');focus?.focus();}});
 window.addEventListener('hashchange',()=>routeChanged());
 document.addEventListener('kepler:plan-changed',()=>{if(!route)renderFolders()});
 document.addEventListener('kepler:attendance-overview',e=>{attendance=e.detail;if(!route)renderFolders();uiQueryAll('[data-course-signal]').forEach(el=>{const course=data.courses.find(c=>c.id===el.dataset.courseSignal);if(course)el.innerHTML=signalHTML(course)});if(route&&!route.missing){const c=route.course,s=signal(c);if($('[data-course-attendance-text]'))$('[data-course-attendance-text]').textContent=s.text;if($('[data-course-attendance-time]'))$('[data-course-attendance-time]').textContent=attendance.updatedAt?'Yerel kayıt: '+stamp(attendance.updatedAt)+' İstanbul':'Bulut kayıt zamanı bilinmiyor.';}});
 routeChanged(false);
 fetch('class-files.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Inventory unavailable');return r.json()}).then(inventory=>{data.classFiles=inventory;if(route)routeChanged(false);else renderFolders();}).catch(()=>{data.inventoryUnavailable=true;if(route)renderDetail();else renderFolders();});
}
export function courseWorkspaceFailed(){
 $('#courseGrid').setAttribute('aria-busy','false');$('#folderResult').textContent='Ders verisine erişilemedi.';$('#courseGrid').innerHTML='<div class="workspace-state"><h3>Klasörler yüklenemedi.</h3><p>Veri dosyası okunamadı; boş ders listesi olarak yorumlanmamalı. Sayfayı yenileyerek tekrar deneyebilirsin.</p><button type="button" class="workspace-button" id="retryWorkspace">Sayfayı yeniden yükle</button></div>';$('#retryWorkspace').addEventListener('click',()=>location.reload());
}
